const activeGMs = game.users.filter(u => u.active && u.isGM).sort((a,b) => a.id.localeCompare(b.id));
if (!activeGMs.length || game.user.id !== activeGMs[0].id) return;
const token = event?.data?.token;
const scene = event?.region?.parent ?? canvas?.scene;
if (!scene || !token?.actor) return;

const dbx = foundry.utils.deepClone(scene.getFlag("world", "dicebox") ?? {});
dbx.f1 ??= {};
const recipients = [...new Set([event?.user?.id, ...activeGMs.map(u => u.id)].filter(Boolean))];

if (dbx.f1.innerWardResolved === true) return;

if (dbx.f1.cicadaInstalled !== true) {
  await ChatMessage.create({
    content: `<p>The repeated stone divisions are inert. Nothing answers the cadence of footsteps here.</p>`,
    whisper: recipients
  });
  return;
}

const now = Date.now();
if (now - Number(dbx.f1.lastWardPromptAt ?? 0) < 5000) return;
dbx.f1.lastWardPromptAt = now;
await scene.setFlag("world", "dicebox", dbx);

const confirmed = await foundry.applications.api.DialogV2.confirm({
  window: {title: "F1 — Inner Ward"},
  content: `<p>The completed Cicada is seated. The inner ward is now listening.</p><p>Have the players correctly performed the Measure / Ritual Rhythm established by the prior clues?</p><p>This BUILD intentionally does not invent a sequence that is not present in the campaign source. Confirm only when you adjudicate the performed rhythm as correct.</p>`,
  yes: {label: "Correct Measure"},
  no: {label: "Not Yet"},
  modal: true
});
if (!confirmed) {
  await ChatMessage.create({
    content: `<p>The stone carries the attempted cadence forward, then returns it altered. The inner threshold remains sealed.</p>`,
    whisper: recipients
  });
  return;
}

const reread = foundry.utils.deepClone(scene.getFlag("world", "dicebox") ?? {});
reread.f1 ??= {};
reread.f1.innerWardResolved = true;
reread.f1.innerWardResolvedAt = Date.now();
reread.f1.innerWardResolvedBy = game.user.id;
await scene.setFlag("world", "dicebox", reread);

const gate = Array.from(scene.walls ?? []).find(w => w.getFlag("world","dicebox")?.stableId === "dbx:central-lodge:f1:wall:inner-gate");
if (gate) await scene.updateEmbeddedDocuments("Wall", [{_id: gate.id, ds: CONST.WALL_DOOR_STATES.OPEN}]);

const lights = Array.from(scene.lights ?? []).filter(l => ["ward","threshold"].includes(l.getFlag("world","dicebox")?.group));
if (lights.length) await scene.updateEmbeddedDocuments("AmbientLight", lights.map(l => ({_id: l.id, hidden: false})));

await ChatMessage.create({
  content: `<p>The final interval lands cleanly. The ward answers in the same measure, then falls silent as the sealed stone gives way.</p>`,
  whisper: recipients
});

const activeGMs = game.users.filter(u => u.active && u.isGM).sort((a,b) => a.id.localeCompare(b.id));
if (!activeGMs.length || game.user.id !== activeGMs[0].id) return;
const token = event?.data?.token;
const scene = event?.region?.parent ?? canvas?.scene;
if (!scene || !token?.actor) return;

const dbx = foundry.utils.deepClone(scene.getFlag("world", "dicebox") ?? {});
dbx.f1 ??= {};
if (dbx.f1.cicadaInstalled === true) return;

const actors = [];
for (const u of game.users) {
  if (!u.isGM && u.character && !actors.some(a => a.id === u.character.id)) actors.push(u.character);
}
if (!actors.some(a => a.id === token.actor.id)) actors.push(token.actor);

const inventory = [];
for (const a of actors) {
  for (const item of a.items ?? []) {
    const flags = item.getFlag?.("world", "dicebox") ?? {};
    const stableId = flags.canonicalStableId ?? flags.stableId ?? null;
    inventory.push({actor:a, item, stableId});
  }
}
const findPart = key => inventory.find(x => x.stableId === "dbx:central-lodge:item:" + key);
const parts = {
  body: findPart("infernal-cicada-body"),
  wingI: findPart("cicada-wing-i"),
  wingII: findPart("cicada-wing-ii"),
  wingIII: findPart("cicada-wing-iii"),
  wingIV: findPart("cicada-wing-iv")
};
const missing = Object.entries(parts).filter(([,v]) => !v).map(([k]) => k);

const recipients = [...new Set([event?.user?.id, ...activeGMs.map(u => u.id)].filter(Boolean))];
if (missing.length) {
  await ChatMessage.create({
    content: `<p>The shallow receiving recess does not answer. Its divisions suggest that several separate fitted pieces belong here, but the assembly is incomplete.</p>`,
    whisper: recipients
  });
  return;
}

const holders = Object.values(parts).map(p => `${p.item.name} — ${p.actor.name}`);
const confirmed = await foundry.applications.api.DialogV2.confirm({
  window: {title: "F1 — Infernal Cicada Recess"},
  content: `<p>The party collectively carries every component of the Infernal Cicada:</p><ul>${holders.map(x => `<li>${x}</li>`).join("")}</ul><p>Install the completed assembly into the ancient receiving recess? This records the threshold state but does not delete the Items.</p>`,
  yes: {label: "Install Cicada"},
  no: {label: "Not Yet"},
  modal: true
});
if (!confirmed) return;

dbx.f1.cicadaInstalled = true;
dbx.f1.cicadaInstalledAt = Date.now();
dbx.f1.cicadaInstalledBy = game.user.id;
await scene.setFlag("world", "dicebox", dbx);

const lights = Array.from(scene.lights ?? []).filter(l => l.getFlag("world","dicebox")?.group === "cicada");
if (lights.length) await scene.updateEmbeddedDocuments("AmbientLight", lights.map(l => ({_id: l.id, hidden: false})));

await ChatMessage.create({
  content: `<p>The fitted assembly settles into the recess without a click. A low pressure passes through the stone, and dim infernal light gathers along the receiving channels.</p>`,
  whisper: recipients
});

const activeGMs = game.users.filter(u => u.active && u.isGM).sort((a,b) => a.id.localeCompare(b.id));
if (!activeGMs.length || game.user.id !== activeGMs[0].id) return;
const token = event?.data?.token;
if (!token?.actor) return;
const actor = token.actor;
const state = foundry.utils.deepClone(actor.getFlag("world","dicebox") ?? {});
state.centralLodge ??= {};
state.centralLodge.f1 ??= {};
if (state.centralLodge.f1.resonanceObserved === true) return;
state.centralLodge.f1.resonanceObserved = true;
state.centralLodge.f1.resonanceObservedAt = Date.now();
await actor.setFlag("world","dicebox",state);

const recipients = [...new Set([event?.user?.id, ...activeGMs.map(u => u.id)].filter(Boolean))];
await ChatMessage.create({
  content: `<p>The recesses, pillars, and cut channels repeat at deliberate intervals. Walking between them produces a faint sequence of returning vibrations, closer to measured cadence than decoration.</p>`,
  whisper: recipients
});

const activeGMs = game.users
  .filter(u => u.active && u.isGM)
  .sort((a,b) => a.id.localeCompare(b.id));

if (
  !activeGMs.length ||
  game.user.id !== activeGMs[0].id
) return;

const token = event?.data?.token;
const sourceScene =
  event?.region?.parent ?? canvas?.scene;

if (!token?.actor || !sourceScene) return;

const dbx =
  foundry.utils.deepClone(
    sourceScene.getFlag("world", "dicebox") ?? {}
  );

if (dbx.f1?.innerWardResolved !== true) {
  return;
}

const destination =
  await fromUuid("Scene.HWitOe1wSid7MZ1y.Region.pplHOCmUZOqFymOy");

if (
  !destination ||
  destination.documentName !== "Region"
) {
  console.error(
    "[DiceBox F1→F2] Destination Region unavailable.",
    "Scene.HWitOe1wSid7MZ1y.Region.pplHOCmUZOqFymOy"
  );
  return;
}

const destinationScene =
  destination.parent;

let user =
  game.users.get(event?.user?.id) ?? null;

if (!user || user.isGM) {
  user =
    game.users.find(
      u =>
        u.active &&
        !u.isGM &&
        u.character?.id === token.actor.id
    ) ?? null;
}

if (!user) {
  const owners =
    game.users.filter(
      u =>
        u.active &&
        !u.isGM &&
        token.actor.testUserPermission(
          u,
          CONST.DOCUMENT_OWNERSHIP_LEVELS.OWNER
        )
    );

  if (owners.length === 1) {
    user = owners[0];
  }
}

await destination.teleportToken(
  token,
  {
    placement: "random",
    snap: false,
    pan: true
  }
);

if (user && destinationScene) {
  await destinationScene.pullUsers(
    [user.id]
  );
}

console.log(
  "[DiceBox F1→F2 TRANSITION]",
  {
    status: "PASS",
    userId: user?.id ?? null,
    userName: user?.name ?? null,
    actorId: token.actor.id,
    actorName: token.actor.name,
    destinationSceneId:
      destinationScene?.id ?? null,
    destinationRegionId:
      destination.id
  }
);
